const About = () => {
  return (
   <div>
      <h2>About Us</h2>
      <p>
        We are a team of passionate developers building beautiful and accessible web experiences.
      </p>

      <h3>Our Mission</h3>
      <p>
        To empower businesses with cutting-edge, user-friendly digital solutions.
      </p>

      <h3>Team</h3>
      <ul>
        <li>Alice - Frontend Developer</li>
        <li>Bob - Backend Developer</li>
        <li>Carol - UI/UX Designer</li>
      </ul>
    </div>
  );
};

export default About;
